#!/usr/bin/env bash
# Usage: rtl/scripts/check_pins.sh
# Compares the pin snapshot rtl/fpga/constraints/data2_pins.xdc (comment lines ignored) with the
# master XDC generated by session L: zynq-ebaz/rtl/vivado/constraints/ebaz4205.xdc of this worktree,
# or, if that is absent, the one in /media/patrik/Workspaces/uC/SAdiy-linux. Exit 1 on a difference,
# 2 if no master is reachable.
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/env.sh"

snap="$RTL_DIR/fpga/constraints/data2_pins.xdc"
master="$EBAZ_DIR/rtl/vivado/constraints/ebaz4205.xdc"
[ -f "$master" ] || master="/media/patrik/Workspaces/uC/SAdiy-linux/zynq-ebaz/rtl/vivado/constraints/ebaz4205.xdc"
if [ ! -f "$master" ]; then echo "check_pins: no master XDC found" >&2; exit 2; fi

echo "check_pins: snapshot $snap"
echo "check_pins: master   $master"
strip() { grep -vE '^[[:space:]]*(#|$)' "$1"; }
if diff <(strip "$snap") <(strip "$master"); then
  echo "check_pins: identical"
else
  echo "check_pins: DIFFERENT (update the snapshot from the master)" >&2
  exit 1
fi
